  "Adds bodycams to the register and updates the ones already there, matched by serial number. Who has a bodycam right now never changes by import; that happens only when it is booked out or handed back.": "I engedza khamera dza muvhili kha redzhisitara nahone i vusulusa dzo no vhaho hone, nga u vhambedza nomboro ya serial. Ane a vha na khamera ya muvhili zwino ha shanduki nga u dzhenisa; izwo zwi itea fhedzi musi i tshi bviswa kana i tshi vhuiswa.",
  "Adds firearms to the register and updates the ones already there, matched by serial number. Who holds a firearm right now never changes by import; that happens only when it is booked out or handed back.": "I engedza zwigidi kha redzhisitara nahone i vusulusa zwo no vhaho hone, nga u vhambedza nomboro ya serial. Ane a vha na tshigidi zwino ha shanduki nga u dzhenisa; izwo zwi itea fhedzi musi tshi tshi bviswa kana tshi tshi vhuiswa.",
  "Adds people to the staff register and updates the ones already there, matched by badge number. Nobody gets access: each person is invited afterwards and activates their own account.": "I engedza vhathu kha redzhisitara ya vhashumi nahone i vusulusa vho no vhaho hone, nga u vhambedza nomboro ya bege. A hu na ane a wana ndiswikelelo: muthu muṅwe na muṅwe u a rambiwa nga murahu a vula akhaunthu yawe.",
  "Adds vehicles to the register and updates the ones already there, matched by department and unit number. A vehicle’s status never changes by import: one off the road stays off the road until fleet control returns it.": "I engedza goloi kha redzhisitara nahone i vusulusa dzo no vhaho hone, nga u vhambedza muhasho na nomboro ya yuniti. Tshiimo tsha goloi a tshi shanduki nga u dzhenisa: i si kha bada i dzula i si kha bada u swikela vhulanguli ha goloi vhu tshi i vhuisa.",
  "Adjustment": "Mulugiso",
  "Admin": "Mulanguli",
