  "Answer every question honestly. Your answers and submission time are recorded for supervisor review. Questions marked": "Fhindulani mbudziso iṅwe na iṅwe nga u fulufhedzea. Phindulo dzaṋu na tshifhinga tsha u rumela zwi a ṅwalwa uri mulavhelesi a zwi ṱole. Mbudziso dzo swaywaho",
