  "EVIDENCE ({n})": "VHUṰANZI ({n})",
  "Each call sign is a row: pick the member for it.": "Dzina ḽiṅwe na ḽiṅwe ḽa u vhidzana ndi mutalo: nangani murado waḽo.",
  "Each call sign is one duty slot: where it patrols, its hours, its break and the rank it needs. Duty Allocation books staff onto these.": "Dzina ḽiṅwe na ḽiṅwe ḽa u vhidzana ndi tshikhala tshithihi tsha mushumo: hune ḽa fhaṱa, awara dzaḽo, mbuno yaḽo na vhuimo vhune ḽa vhu ṱoḓa. Duty Allocation i ṅwalisa vhashumi kha zwenezwo.",
  "Each call sign with its area, hours and the rank it needs.": "Dzina ḽiṅwe na ḽiṅwe ḽa u vhidzana na vhupo haḽo, awara na vhuimo vhune ḽa vhu ṱoḓa.",
  "Each day's reports, by where they stand.": "Mivhigo ya ḓuvha ḽiṅwe na ḽiṅwe, u ya nga he ya ima hone.",
  "Each link or code works once and expires after {invitationTtlHours} hours. Sending again cancels the old one.": "Vhukwamani kana khoudu iṅwe na iṅwe i shuma luthihi nahone i fhela nga murahu ha awara dza {invitationTtlHours}. U rumela hafhu zwi khantsela ya kale.",
  "Each member’s record as the old system kept it: numbers, rank, station, section, weekend group, contacts, LEO record and screen access.": "Rekhodo ya murado muṅwe na muṅwe sa zwe sisiṱeme ya kale ya i vhulunga: nomboro, vhuimo, tshiṱitshi, khethekanyo, tshigwada tsha mafhelo a vhege, vhukwamani, rekhodo ya LEO na u swikelela kha tshikirini.",
  "Each patient and how bad they are": "Mulwadze muṅwe na muṅwe na uri u kha tshiimo tshi vhifhaho lungafhani",
  "Each person gets their own invitation, as their confirmed role, by the route shown: email where HR gave an address, SMS where there is only a cellphone{value}, otherwise a printed code. Each link or code works once and expires after its set time.": "Muthu muṅwe na muṅwe u wana tshirambo tshawe, sa mushumo wawe wo khwaṱhisedzwaho, nga nḓila yo sumbedzwaho: imeili hune HR ya ṋea diresi, SMS hune ha vha na selefoni fhedzi{value}, arali zwi si zwone khoudu yo gandiswaho. Vhukwamani kana khoudu iṅwe na iṅwe i shuma luthihi nahone i fhela nga murahu ha tshifhinga tshayo tsho vhewaho.",
  "Each rule acts at most once per thing per threshold — a call that breaches its SLA raises one alert at each tier, not one every five minutes. Thresholds are stored per rule, so changing “escalate after 10 minutes” to 15 needs no deployment. Every change and every manual run is written to the audit trail with your name on it.": "Mulayo muṅwe na muṅwe u shuma luthihi fhedzi kha tshithu tshiṅwe na tshiṅwe kha mukano muṅwe na muṅwe — founu ine ya fhira SLA yayo i vusa tsevho nthihi kha vhuimo vhuṅwe na vhuṅwe, hu si nthihi minetse iṅwe na iṅwe ya ṱhanu. Mikano i vhulungwa nga mulayo muṅwe na muṅwe, nga zwenezwo u shandukisa \"engedzani nga murahu ha minetse ya 10\" u vha 15 a zwi ṱoḓi u dzheniswa. Tshanduko iṅwe na iṅwe na u shuma huṅwe na huṅwe nga tshanḓa zwi ṅwalwa kha mukondo wa ṱhoḓisiso na dzina ḽaṋu.",
  "Each service's identity — crest, colours and naming — as it appears across the platform, the responder app and printed reports.": "Vhuṋe ha tshumelo iṅwe na iṅwe — tshiga, mivhala na madzina — sa zwine zwa bvelela kha phulathifomo yoṱhe, kha app ya vhafhinduli na kha mivhigo yo gandiswaho.",
