  "Emulators and simulators cannot register for push. Alerts still arrive while the app is open.": "Dzi-emulator na dzi-simulator a dzi koni u ḓiṅwalisela ndivhadzo. Tsevho dzi kha ḓi swika musi app yo vulwa.",
