  "Fight / Physical Altercation": "Nndwa / Phambano ya muvhili",
  "Figures": "Mbalo",
  "Figures come from incidents you responded to in the app, as lead or backup. Times are measured on incidents you led.": "Mbalo dzi bva kha zwiitea zwe na zwi fhindula nga app, sa murangaphanḓa kana thuso. Zwifhinga zwi kalwa kha zwiitea zwe na zwi ranga phanḓa.",
  "File": "Rumelani",
