  "File this fire report?": "Rumelani uyu muvhigo wa mulilo?",
  "File this report?": "Rumelani uyu muvhigo?",
  "Filed (SAST)": "Zwo rumelwa (SAST)",
  "Filed by {value}{value2}{value3}{value4}": "Zwo rumelwa nga {value}{value2}{value3}{value4}",
  "Filed by {value}{value2}{value3}{value4}{value5}": "Zwo rumelwa nga {value}{value2}{value3}{value4}{value5}",
  "Filed from the desk by {value}{value2}.": "Zwo rumelwa u bva kha desike nga {value}{value2}.",
  "Filed reports are permanent and visible to dispatch and command.": "Mivhigo yo rumelwaho ndi ya tshoṱhe nahone i vhonwa nga vharumeli na vhalanguli.",
  "Filing report": "Hu khou rumelwa muvhigo",
  "Filing resolves the incident. The report is permanent and visible to command and case managers.": "U rumela zwi tandulula tshiitea. Muvhigo ndi wa tshoṱhe nahone u vhonwa nga vhalanguli na vhalanguli vha milandu.",
  "Filing:": "U rumela:",
  "Filing: {filing}": "U rumela: {filing}",
  "Fill a whole section for some days: pair call signs with staff.": "Ḓadzani khethekanyo yoṱhe lwa maḓuvha a si gathi: ṱanganyani madzina a u vhidzana na vhashumi.",
  "Filled in by Criti": "Zwo ḓadzwa nga Criti",
  "Filled in by Criti. Change it if it is wrong.": "Zwo ḓadzwa nga Criti. Zwi shandukiseni arali zwo khakhea.",
  "Filter": "Khethani",
  "Filter by station and share the list with its commander before shift briefing.": "Khethani nga tshiṱitshi ni kovhelane mutevhe na mulanguli watsho phanḓa ha muṱangano wa tshifithi.",
  "Filter cameras…": "Khethani khamera…",
  "Filter menu…": "Khethani menyu…",
  "Filter navigation": "Khethani u tshimbila",
  "Filters": "Zwikhethi",
  "Find a member: search by name or staff number, or filter by station and rank.": "Wanani murado: ṱolani nga dzina kana nomboro ya mushumi, kana ni khethe nga tshiṱitshi na vhuimo.",
  "Find a name": "Wanani dzina",
  "Find a person": "Wanani muthu",
  "Find a site by name or address": "Wanani fhethu nga dzina kana ḓiresi",
  "Find footage": "Wanani rekhodo",
  "Find someone…": "Wanani muṅwe…",
  "Find your name": "Wanani dzina ḽaṋu",
  "Finding your location…": "Hu khou ṱoḓwa fhethu haṋu…",
  "Finding your position…": "Hu khou ṱoḓwa he na vha hone…",
  "Fine": "Ndatiso",
  "Fine Payments": "Mbadelo dza ndatiso",
  "Fine not found": "Ndatiso a yo ngo wanala",
  "Fines": "Ndatiso",
  "Fines & tickets": "Ndatiso na thikhithi",
  "Fines ({length})": "Ndatiso ({length})",
  "Fines Account": "Akhaunthu ya ndatiso",
  "Fines Register": "Redzhisitara ya ndatiso",
  "Fines account": "Akhaunthu ya ndatiso",
  "Fines are issued by Metro Police officers, supervisors and captains.": "Ndatiso dzi bviswa nga vhaofisiri vha Metro Police, vhalavhelesi na vhakaputeni.",
  "Fines are not available yet. If migration 0057 has not been run, run it in Supabase.": "Ndatiso a dzi athu wanala. Arali migration 0057 i songo itwa, i iteni kha Supabase.",
  "Fines you issue appear here, with their slips.": "Ndatiso dzine na dzi bvisa dzi bvelela fhano, na mabammbiri adzo.",
  "Finish": "Fhedzani",
  "Finish and send to {desks}": "Fhedzani ni rumele kha {desks}",
  "Finish the call": "Fhedzani founu",
  "Finish this call": "Fhedzani founu iyi",
