  "For a call that will never have a report: a hoax, a duplicate, or the caller cancelled.{value}": "Kha luṱingo lune lwa sa ḓo vha na muvhigo: zwa u tamba, lwo dovholwaho, kana muvhidzi o khantsela.{value}",
  "For a notice issued in error. It stays on the register, marked cancelled, with your reason. Refund any money first.": "Kha ndivhadzo yo bviswaho nga vhukhakhi. I dzula kha redzhisiṱara, yo swayiwa sa yo khantselwaho, na tshiitisi tshaṋu. Vhuedzedzani tshelede iṅwe na iṅwe u thoma.",
  "For a notice written in a notice book. Copy it exactly as written, with the printed notice number. Notices at the roadside are issued on the phone, where the infringer signs.": "Kha ndivhadzo yo ṅwaliwaho kha bugu ya ndivhadzo. I kopeni nga hune ya ṅwaliwa ngaho, na nomboro ya ndivhadzo yo gandiswaho. Ndivhadzo dza kha bada dzi bviswa kha luṱingo, hune mutshinyi a saina hone.",
  "For example towards the taxi rank": "Tsumbo, u livha kha rennga ya dzithekisi",
  "For example: radio from a security guard": "Tsumbo: radio i bvaho kha mulindi wa tsireledzo",
  "For example: the caller rang back with the right address": "Tsumbo: muvhidzi o dovha a founela na diresi yo teaho",
  "For leave on a form the member handed in, sick leave, or an absence such as AWOL. It is approved as captured and their duty in those dates is marked.": "Kha u awela kha fomo ye murado a i ṋea, u awela nga mulandu wa vhulwadze, kana u sa vha hone sa AWOL. Hu tendelwa sa zwe zwa ṅwalwa ngaho nahone mushumo wawe kha maḓuvha ayo u a swaiwa.",
  "For the whole organisation. Office-hours rotations skip them, and they are not counted as leave days.": "Ya dzangano ḽoṱhe. U shandukana ha awara dza ofisi zwi a dzi pfuka, nahone a dzi vhalwi sa maḓuvha a u awela.",
  "For their shift": "Kha tshifithi tshavho",
  "For you, your role, your department and everyone.": "Kha inwi, mushumo waṋu, muhasho waṋu na vhoṱhe.",
