  "How can response be improved in the future?": "Phindulo i nga khwiniswa hani tshifhingani tshi ḓaho?",
  "How configuration works": "Nḓila ine nzudzanyo ya shuma ngayo",
  "How did it end for {label}?": "Zwo fhela hani kha {label}?",
  "How do you know they are there? e.g. Called the officer; seen on the bodycam": "Ni zwi ḓivha hani uri vha hone? tsumbo. Ndo founela muofisiri; vho vhonwa kha bodycam",
  "How does on scene by GPS work?": "U vha fhethu nga GPS zwi shuma hani?",
  "How far along is she?": "O ḓihwala tshifhinga tshingafhani?",
  "How long has it lasted?": "Zwo dzhia tshifhinga tshingafhani?",
  "How long this has stood": "Tshifhinga tshine izwi zwa vha zwo ima ngatsho",
  "How many are hurt": "Ndi vhangana vho huvhalaho",
  "How many are trapped, and where?": "Ndi vhangana vho farekanaho, nahone vha ngafhi?",
  "How many are trapped?": "Ndi vhangana vho farekanaho?",
  "How many escaped, and what do they look like?": "Ndi vhangana vho shavhaho, nahone vha vhonala hani?",
  "How many feeds": "Ndi dzi-feed dzingana",
  "How many homes are burning?": "Ndi haya dzingana dzi swaho?",
  "How many homes are damaged?": "Ndi haya dzingana dzo tshinyalaho?",
  "How many homes are flooded?": "Ndi haya dzingana dzo ḓalaho maḓi?",
  "How many passengers are hurt?": "Ndi vhaṋameli vhangana vho huvhalaho?",
  "How many people": "Ndi vhathu vhangana",
  "How many people are hurt?": "Ndi vhathu vhangana vho huvhalaho?",
  "How many people are involved?": "Ndi vhathu vhangana vho kwameaho?",
  "How many people need shelter?": "Ndi vhathu vhangana vha ṱoḓaho vhudzulo?",
  "How many people were inside?": "Ho vha hu na vhathu vhangana ngomu?",
  "How many people, and any weapons?": "Ndi vhathu vhangana, nahone hu na zwiṱhavhi?",
  "How many people, and where?": "Ndi vhathu vhangana, nahone vha ngafhi?",
  "How many people?": "Ndi vhathu vhangana?",
  "How many suspects and vehicles?": "Ndi vhasumbedzwa na goloi dzingana?",
  "How many suspects, and what weapons?": "Ndi vhasumbedzwa vhangana, nahone ndi zwiṱhavhi zwifhio?",
  "How many suspects?": "Ndi vhasumbedzwa vhangana?",
  "How many vehicles?": "Ndi goloi dzingana?",
  "How much leave do I have left?": "Ndo salelwa nga maḓuvha mangana a u awela?",
  "How much of the body is burnt?": "Ndi tshipiḓa tshingafhani tsha muvhili tsho swaho?",
  "How often this rule is evaluated. The scheduler ticks every 5 minutes, so anything below that runs every tick.": "Uri mulayo uyu u ṱolwa kangana. Mudzudzanyi u shuma minithi iṅwe na iṅwe ya 5, ngauralo tshiṅwe na tshiṅwe tshi re fhasi ha zwenezwo tshi shuma tshifhinga tshoṱhe.",
  "How serious": "Zwi khombo lungana",
  "How the call came in": "Nḓila ye luṱingo lwa da ngayo",
  "How the notice was served": "Ndivhadzo yo ṋewa hani",
  "How they receive it": "Nḓila ye vha zwi wana ngayo",
  "How this page works": "Siaṱari iḽi ḽi shuma hani",
  "How this works": "Nḓila ine izwi zwa shuma ngayo",
  "How to dispatch": "Nḓila ya u rumela",
  "How was information obtained?": "Mafhungo o wanala hani?",
