  "Humidity: {humidity}%": "Mutsho: {humidity}%",
  "Hurt: {who}": "O huvhalaho: {who}",
  "Hydrant map and register.": "Mapa na redzhisiṱara ya dzihayidirenthe.",
  "Hydrant register": "Redzhisiṱara ya dzihayidirenthe",
  "Hydrant register →": "Redzhisiṱara ya dzihayidirenthe →",
  "Hydrants": "Dzihayidirenthe",
  "Hydrants operational": "Dzihayidirenthe dzi shumaho",
  "Hydraulic": "Hydraulic",
  "Hyundai": "Hyundai",
  "I am at the scene": "Ndi fhethu",
  "I am not drawing a firearm this shift (e.g. mine is not on the armoury register). This is recorded on my start-of-shift record.": "A thi khou dzhia tshigidi kha tshifithi itshi (tsumbo. tshanga a tshi kha redzhistara ya vhuvhulungelo ha zwigidi). Izwi zwi ṅwalwa kha rekhodo yanga ya u thoma tshifithi.",
  "I am not wearing a bodycam this shift. My reason is on my start-of-shift record and my supervisor sees it.": "A thi khou ambara bodycam kha tshifithi itshi. Tshiitisi tshanga tshi kha rekhodo yanga ya u thoma tshifithi nahone mulanguli wanga u a tshi vhona.",
  "I checked this ambulance and its stock myself, and the answers above are accurate.": "Ndo ṱola ambulennse iyi na zwishumiswa zwayo nṋe muṋe, nahone phindulo dzi re afho nṱha dzi a ṱanganedzea.",
  "I confirm that I have physically inspected the above vehicle and that the information recorded is accurate to the best of my knowledge. Any faults noted must be reported to the immediate supervisor and recorded in the official pocket book.": "Ndi khwaṱhisedza uri ndo ṱola goloi i re afho nṱha nga ṋama nahone uri mafhungo o ṅwalwaho a a ṱanganedzea u ya nga zwine nda zwi ḓivha. Vhukhakhi vhuṅwe na vhuṅwe ho vhonwaho vhu fanela u vhigwa kha mulanguli nga u ṱavhanya na u ṅwalwa kha bugu ya tshiofisi ya pokhoni.",
  "I explained the court date, and that paying the admission of guilt is a conviction and may give a criminal record.": "Ndo ṱalutshedza ḓuvha ḽa khothe, na uri u badela u ṱanganedza mulandu ndi u haṱulelwa nahone zwi nga ṋea rekhodo ya vhutshinyi.",
  "I explained the notice and the options: pay within 32 days for the discount, apply to pay in instalments (AARTO 04), or make a representation (AARTO 08).": "Ndo ṱalutshedza ndivhadzo na khetho: badelani nga maḓuvha a 32 uri ni wane ṱhukhukhu, humbelani u badela nga zwipiḓa (AARTO 04), kana ni ite khumbelo ya u ḓiimelela (AARTO 08).",
  "I have an activation code": "Ndi na khoudu ya u thoma",
  "I have read the POPIA notice (version {POPIA_NOTICE_VERSION})": "Ndo vhala ndivhadzo ya POPIA (vesheni {POPIA_NOTICE_VERSION})",
  "I have read this shift": "Ndo vhala tshifithi itshi",
  "I know how your department works and I can read the live board your role can see. Ask me anything, or tell me what to do. I prepare it, and nothing changes until you confirm.": "Ndi a ḓivha uri muhasho waṋu u shuma hani nahone ndi nga vhala bodo i tshilaho ine mushumo waṋu wa i vhona. Mmbudziseni zwiṅwe na zwiṅwe, kana ni mmbudze zwine nda fanela u zwi ita. Ndi a zwi lugisela, nahone a hu na zwine zwa shanduka u swikela ni tshi khwaṱhisedza.",
  "I know your shift, your calls, your leave and your kit. Ask me anything about your work, in your own words. I explain and show you where to go; you do the work.": "Ndi a ḓivha tshifithi tshaṋu, founu dzaṋu, u awela haṋu na zwishumiswa zwaṋu. Mmbudziseni zwiṅwe na zwiṅwe nga ha mushumo waṋu, nga maipfi aṋu. Ndi a ṱalutshedza nahone nda ni sumbedza hune na fanela u ya hone; inwi ni ita mushumo.",
  "I personally completed these checks and confirm that the answers and any defects recorded are accurate.": "Ndo ita tsedzuluso idzi nṋe muṋe nahone ndi khwaṱhisedza uri phindulo na vhukhakhi ho ṅwalwaho zwi a ṱanganedzea.",
  "I will use HikTech only for official duties and keep my password private": "Ndi ḓo shumisa HikTech kha mishumo ya tshiofisi fhedzi nahone nda vhulunga phasiwede yanga i tshiphiri",
  "I'm on scene — it has not changed": "Ndi fhethu — a zwo ngo shanduka",
  "I've restocked — check again": "Ndo ḓadza hafhu — ṱolani hafhu",
