  "Incidents routed to your department reach this phone even when the screen is locked. High and Critical incidents open a full-screen alert you must acknowledge.": "Zwiitea zwi rumelwaho kha muhasho waṋu zwi swika kha founu iyi naho tshikirini tsho khiyiwa. Zwiitea zwa Nṱha na zwa Khombo zwi vula tsivhudzo ya tshikirini tshoṱhe ine na fanela u i ṱanganedza.",
