  "Issuing fines from the phone is not enabled for your organisation.": "U ṋea ndifho nga founu a zwo ngo tendelwa kha dzangano ḽaṋu.",
  "Isuzu": "Isuzu",
  "It gets the next CH- number; the arresting officer is you unless noted.": "I wana nomboro i tevhelaho ya CH-; muofisiri a faraho ndi inwi nga nnḓa ha musi zwo ṅwalwa.",
  "It gets the next DM- number; the assignee is alerted at once.": "I wana nomboro i tevhelaho ya DM-; o avhelwaho u ḓivhadzwa nga u ṱavhanya.",
  "It gets the next SM- number. Service is recorded from the register below.": "I wana nomboro i tevhelaho ya SM-. U ṋewa hu ṅwalwa u bva kha redzhistara i re fhasi.",
  "It gets the next WA- number. Court and expiry as issued.": "I wana nomboro i tevhelaho ya WA-. Khothe na u fhela ha tshifhinga zwi tshi nga zwe zwa ṋewa ngazwo.",
  "It goes for repair and your supervisor is told.": "I ya u lugiswa nahone mulanguli waṋu u a ḓivhadzwa.",
  "It goes to the armourer for repair instead of back into service.": "I ya kha mulugisi wa zwigidi u itela u lugiswa nṱhani ha u vhuyelela mushumoni.",
  "It is alleged that…": "Hu ambiwa uri…",
  "It is held on this phone and sends automatically, ahead of everything else, the moment you have signal. Do not wait — SMS or call the control room now.": "Yo vhulungwa kha founu iyi nahone i rumelwa nga yoṱhe, phanḓa ha zwoṱhe, nga u ṱavhanya musi ni tshi wana siginala. Ni songo lindela — rumelani SMS kana ni founele control room zwino.",
  "It is in the description, and follows your answers until you type.": "I kha ṱhaluso, nahone i tevhela phindulo dzaṋu u swikela ni tshi ṅwala.",
  "It is waiting for signal and sends automatically.": "I khou lindela siginala nahone i rumelwa nga yoṱhe.",
  "It may belong to another officer, or the link is out of date.": "I nga vha ya muṅwe muofisiri, kana vhukwamani a vhu tsha shuma.",
  "It may have been closed or reassigned, or it is not for your department.": "I nga vha yo valwa kana ya avhelwa muṅwe, kana a si ya muhasho waṋu.",
  "It may have been reassigned, or you no longer have access to it.": "I nga vha yo avhelwa muṅwe, kana a ni tsha kona u i swikelela.",
  "It may have been reassigned.": "I nga vha yo avhelwa muṅwe.",
  "It may not have reached the server yet.": "I nga vha i sa athu swika kha seva.",
  "It prints on the duty sheet beside their name.": "I gandiswa kha bammbiri ḽa mushumo tsini na dzina ḽavho.",
  "It resolves {incident_number} and becomes a permanent record — it cannot be edited or deleted afterwards.": "I tandulula {incident_number} nahone ya vha rekhodo i sa fheli — a i nga shandukiswi kana ya phumulwa nga murahu.",
  "It resolves {incident_number}.": "I tandulula {incident_number}.",
  "It sends when you have signal.": "I rumelwa musi ni na siginala.",
  "It stays on the record with your name and the reason.": "I dzula kha rekhodo na dzina ḽaṋu na tshiitisi.",
  "It stays on this phone under your account and sends the next time you sign in with signal.": "I dzula kha founu iyi nga fhasi ha akhaunthu yaṋu nahone i rumelwa tshifhinga tshi tevhelaho musi ni tshi dzhena ni na siginala.",
  "It will go to maintenance, not back into service.": "I ḓo ya kha u ṱhogomelwa, hu si u vhuyelela mushumoni.",
