  "No signal, and this device only remembers you for one shift. Sign in when you have signal.": "A hu na siginala, nahone tshishumiswa itshi tshi ni humbula lwa tshifithi tshithihi fhedzi. Dzhenani musi ni na siginala.",
  "No signal. The notice is safe on this phone and sends itself when there is signal. Print the provisional slip now.": "A hu na siginala. Ndivhadzo yo tsireledzea kha founu iyi nahone i ḓirumela musi hu na siginala. Gandisani tshiliphi tsha tshifhinganyana zwino.",
  "No signal. Without signal this device only signs you back in after you have handed it over. Sign in when you have signal.": "A hu na siginala. Hu si na siginala tshishumiswa itshi tshi ni dzhenisa hafhu fhedzi nga murahu ha musi no tshi ṋekedza. Dzhenani musi ni na siginala.",
  "No signal. You can still issue the fine: it sends itself when the phone finds a signal, and the slip prints now.": "A hu na siginala. Ni kha ḓi nga ṋea ndifho: i ḓirumela musi founu i tshi wana siginala, nahone tshiliphi tshi gandiswa zwino.",
  "No signal. Your route is kept on this phone and sends when signal returns.": "A hu na siginala. Nḓila yaṋu i vhulungwa kha founu iyi nahone i rumelwa musi siginala i tshi vhuya.",
