  "Official After-Action Reports. Filing one resolves the incident.": "Mivhigo ya Tshiofisi ya nga Murahu ha Nyito. U rumela muthihi zwi tandulula tshiitea.",
  "Official insignia belong to the municipality and its services, so the platform ships none — upload each department's real crest here and it appears everywhere immediately. Until then a monogram badge renders in that department's colours, so nothing ever looks unfinished. PNG or SVG with a transparent background works best; square crops read cleanest at small sizes.": "Zwiga zwa tshiofisi ndi zwa masipala na tshumelo dzawo, ngauralo pulatifomo a i zwi ḓisi — longelani tshiga tsha vhukuma tsha muhasho muṅwe na muṅwe fhano nahone tshi bvela huṅwe na huṅwe nga u ṱavhanya. U swika ndi hone bedzhi ya maḽeḓere a u thoma i tshi sumbedzwa nga mivhala ya muhasho wonoyo, ngauralo a hu na tshithu tshi vhonalaho tshi songo fhedzwa. PNG kana SVG i re na murahu u vhonalaho i shuma zwavhuḓi; zwifanyiso zwa sikwea zwi vhalea zwavhuḓi musi zwi zwiṱuku.",
  "Official name": "Dzina ḽa tshiofisi",
