  "On parade, members sign on, sign off and sign for overtime on the paper.": "Kha pharedi, miraḓo i saina musi i tshi thoma, musi i tshi fhedza na nga tshifhinga tsho engedzwaho kha bammbiri.",
  "On ramp/slipway": "Nḓila ya u dzhena kha bada khulwane",
  "On record": "Kha rekhodo",
  "On scene": "Fhethu",
  "On scene is marked by itself when you get there.": "U vha fhethu zwi swayiwa nga zwoṱhe musi ni tshi swika hone.",
  "On scene is marked when you arrive": "U vha fhethu zwi swayiwa musi ni tshi swika",
  "On scene is set by the crew’s own phone reaching the scene. Click a strip to see the crew.": "U vha fhethu zwi dzudzanywa nga founu ya tshigwada nga yoṱhe musi i tshi swika fhethu. Kwatani mutalo u vhona tshigwada.",
  "On scene. Fill the report as the crew tells you.": "Vha fhethu. Ḓadzani muvhigo sa zwine tshigwada tsha ni vhudza zwone.",
  "On standby": "U khou lindela",
