  "Once approved, {value} prints the activation slip and hands it over in person.": "Musi zwo no tendelwa, {value} u gandisa bammbiri ḽa u vula a ḽi ṋekedza nga tshanḓa.",
  "Once it has been cleaned, fleet control returns it to service.": "Musi yo no kuniwa, vhalanguli vha dzigoloi vha i vhuisela mushumoni.",
  "One answer needs fixing": "Phindulo nthihi i ṱoḓa u khakhululwa",
  "One at a time. For many, use the import with the template.": "Nthihi nga tshifhinga. Kha nnzhi, shumisani u dzhenisa nga thempulethe.",
  "One at a time. For the whole armoury, use the import with the template.": "Tshithihi nga tshifhinga. Kha vhuvhulungelo hoṱhe ha zwibetshi, shumisani u dzhenisa nga thempulethe.",
  "One at a time. For the whole fleet, use the import with the template.": "Nthihi nga tshifhinga. Kha dzigoloi dzoṱhe, shumisani u dzhenisa nga thempulethe.",
  "One person": "Muthu muthihi",
  "One thing is missing:": "Hu na tshithu tshithihi tshi siho:",
  "Only Staff Maintenance and the member can see this.": "Ndi Ndondolo ya Vhashumi na muraḓo fhedzi vhane vha nga vhona izwi.",
  "Only a translator for this language approves. You can save drafts.": "Ndi muṱalutshedzi wa luambo ulu fhedzi ane a tendela. Ni nga vhulunga zwiṱoḓwa.",
  "Only approved translations are shown on the screens. Everything else shows in English.": "Ṱhalutshedzo dzo tendelwaho fhedzi dzi sumbedzwa kha zwikirini. Zwiṅwe zwoṱhe zwi sumbedzwa nga Luisimane.",
  "Only fines I issued": "Ndifho dzo ṋewaho nga nṋe fhedzi",
  "Only if there is no emergency. Why?": "Fhedzi arali hu si na tshiwo. Ndi ngani?",
  "Only me": "Nṋe fhedzi",
  "Only officers who went on duty in the app after today's start of shift are listed. Distance is straight-line from their last GPS heartbeat; ETA assumes {speedKmh} km/h with a {roadFactor}× road factor (Admin → Operations Settings).": "Hu ṅwalwa fhedzi vhaofisiri vho dzhenaho mushumoni kha app nga murahu ha u thoma ha tshifithi tsha ṋamusi. Tshikhala ndi mutalo wo livhaho u bva kha siginala yavho ya u fhedza ya GPS; ETA i dzhia {speedKmh} km/h na tshiṱaluli tsha bada tsha {roadFactor}× (Admin → Mbekanyo dza Mushumo).",
  "Only one patient": "Mulwadze muthihi fhedzi",
  "Only someone senior to the member, in their department, can approve. Nobody approves their own.": "Ndi muthu wa nṱha ha muraḓo fhedzi, kha muhasho wawo, ane a nga tendela. A hu na ane a ḓitendela.",
  "Only the firefighter leading this incident files its fire report.": "Ndi mudzimamulilo ane a ranga tshiitea itshi fhedzi ane a rumela muvhigo watsho wa mulilo.",
  "Only the lead officer on this incident can file its report.": "Ndi muofisiri ane a ranga kha tshiitea itshi fhedzi ane a nga rumela muvhigo watsho.",
  "Only the officer leading this incident files its post-mortem.": "Ndi muofisiri ane a ranga tshiitea itshi fhedzi ane a rumela tsenguluso yatsho ya nga murahu.",
  "Only the paramedic leading this incident files its patient report.": "Ndi paramediki ane a ranga tshiitea itshi fhedzi ane a rumela muvhigo watsho wa mulwadze.",
  "Only the person who logged {number}, or the control room, can finish it.": "Ndi muthu we a ṅwala {number} fhedzi, kana rumu ya ndango, ane a nga i fhedza.",
  "Only the {desks} dispatch desk receives this call.": "Ndi dese ya u rumela ya {desks} fhedzi ine ya wana founu iyi.",
  "Only the {desks} dispatch desks receive this call.": "Ndi dzidese dza u rumela dza {desks} fhedzi dzine dza wana founu iyi.",
  "Only translators and administrators work on translations.": "Ndi vhaṱalutshedzi na vhalanguli fhedzi vhane vha shuma nga ṱhalutshedzo.",
