  "Open an account to change its role or deactivate it. Every change needs a reason, is recorded permanently, and reaches the person straight away. New people join by invitation.": "Vulani akhaunthu u shandukisa mushumo wayo kana u i dzima. Tshanduko iṅwe na iṅwe i ṱoḓa tshiitisi, i ṅwalwa tshoṱhe, nahone i swika kha muthu nga u ṱavhanya. Vhathu vhaswa vha dzhena nga u rambiwa.",
