  "Road traffic offences carry the AARTO Schedule 3 charge code and penalty; by-law offences carry the by-law section and the admission of guilt amount. Enter both from the official schedules, then verify. Changing a verified code or amount takes the verification off until someone checks it again.": "Milandu ya bada i fara khoudu ya mulandu ya AARTO Schedule 3 na ndifho; milandu ya mulayo wa masipala i fara khethekanyo ya mulayo na tshelede ya u tenda mulandu. Dzhenisani zwoṱhe zwivhili u bva kha zwiṱaṱisi zwa tshiofisi, ni khwaṱhisedze. U shandukisa khoudu kana tshelede yo khwaṱhisedzwaho zwi bvisa khwaṱhisedzo u swika muthu a tshi i ṱola hafhu.",
  "Road traffic offences on AARTO 01 notices; by-law offences on Section 56 (offender present) or Section 341 (unattended vehicle) notices. Every charge has its own FN- number, and a served notice can never be edited or deleted — only cancelled, with a reason.": "Milandu ya bada kha ndivhadzo dza AARTO 01; milandu ya mulayo wa masipala kha ndivhadzo dza Khethekanyo 56 (mutshinyi wa mulayo u hone) kana Khethekanyo 341 (goloi i songo ṱhogomelwaho). Mulandu muṅwe na muṅwe u na nomboro yawo ya FN-, nahone ndivhadzo yo ṋekedzwaho a i nga shandukiswi kana u phumulwa — i nga khantseliwa fhedzi, nga tshiitisi.",
