  "Sent out — waiting for an officer to respond. Dispatching again re-alerts everyone on duty.": "Zwo rumelwa — hu khou lindelwa muofisiri uri a fhindule. U rumela hafhu zwi sevhedza hafhu vhoṱhe vha re mushumoni.",
