  "Sent to everyone on duty. The first to respond leads; others can join as backup.": "Zwo rumelwa kha vhoṱhe vha re mushumoni. Ane a fhindula u thoma u a ranga; vhaṅwe vha nga ṱanganela sa vhathusi.",
  "Sent to everyone on standby. The first to respond leads; others can join as backup.": "Zwo rumelwa kha vhoṱhe vha khou lindela. Ane a fhindula u thoma u a ranga; vhaṅwe vha nga ṱanganela sa vhathusi.",
