  "Showing the first {localeString} rows — there are more. Totals below cover only what is shown, so narrow the filters or raise the row limit before relying on them.": "Hu sumbedzwa mitalo ya u thoma ya {localeString} — hu na miṅwe. Tshivhalo tshoṱhe afho fhasi tshi katela fhedzi zwi sumbedzwaho, ngauralo fhungudzani zwikali kana ni engedze mukano wa mitalo ni sa athu zwi fulufhela.",
