  "Shows how many in the department would be away if granted.": "Zwi sumbedza uri ndi vhangana kha muhasho vhane vha nga vha vha si ho arali zwa tendelwa.",
  "Shows unpaid fines on the city’s register from every officer: fine numbers, offences, amounts and where each stands. Names and addresses on other officers’ fines are not shown. Every check is recorded.": "Zwi sumbedza ndifho dzi sa athu badelwa kha redzhistara ya ḓorobo u bva kha vhaofisiri vhoṱhe: nomboro dza ndifho, milandu, tshelede na hune iṅwe na iṅwe ya vha hone. Madzina na ḓiresi kha ndifho dza vhaṅwe vhaofisiri a zwi sumbedzwi. U ṱola hoṱhe hu a ṅwalwa.",
