  "Take a moment to check in. Answer each question honestly before starting operational duty.": "Dzhiani tshifhinganyana u ḓiṱola. Fhindulani mbudziso iṅwe na iṅwe nga u fulufhedzea ni sa athu thoma mushumo.",
