  "Takes effect on their next sign-in. Their existing records do not move — a person changes tenant; history stays where it happened.": "Zwi shuma musi vha tshi dzhena hafhu. Rekhodo dzavho dzi re hone a dzi tshimbili — muthu u shandukisa muhiri; ḓivhazwakale i dzula hune ya itea hone.",
