  "Upload evidence": "Longani vhuṱanzi",
  "Upload the day’s receipts from the cashier or the bank. Each row is matched to a fine by its FN- number or its notice number, and recorded with the date on the receipt — so a payment made inside the 32 days keeps the AARTO discount even when it is captured later. A receipt already on a fine is skipped, so importing the same file twice records nothing twice.": "Longani rasiṱi dza ḓuvha u bva kha mukhasheri kana bannga. Mutalo muṅwe na muṅwe u tshimbilelaniswa na ndifho nga nomboro yayo ya FN- kana nomboro ya ndivhadzo yayo, nahone u ṅwalwa na ḓuvha ḽi re kha rasiṱi — ngauralo mbadelo yo itwaho nga ngomu ha maḓuvha a 32 i vhulunga tsevho ya AARTO naho yo dzheniswa nga murahu. Rasiṱi yo no vha kha ndifho i a fhiriwa, ngauralo u dzhenisa faela i fanaho luvhili a hu ṅwali tshithu luvhili.",
