  "What each tenant's portal offers, module by module — hide one for the whole organisation or deny it to specific roles. Rules only ever subtract from the built-in role matrix, and take effect everywhere within a minute.": "Zwine phothali ya muhiri muṅwe na muṅwe ya zwi ṋea, mojulu nga mojulu — dzumbani muthihi kha dzangano ḽoṱhe kana ni u hanele mishumo i ngaho. Milayo i bvisa fhedzi kha mutevhe wa mishumo wo fhaṱiwaho ngomu, nahone i shuma huṅwe na huṅwe nga minethe.",
  "What escort, and which route": "U felekedza hufhio, nahone nḓila ifhio",
