  "What is burning?": "Ndi mini tshi fhisaho?",
  "What is it carrying?": "I hwele mini?",
  "What is sent to you, your role, your department and everyone lands here. High and Critical incidents also open a full-screen alert you have to acknowledge.": "Zwi rumelwaho kha inwi, kha mushumo waṋu, kha muhasho waṋu na kha vhoṱhe zwi swika fhano. Zwiitea zwa Nṱha na zwa Ndeme vhukuma zwi vula hafhu tsevhedzo ya tshikirini tshoṱhe ine na tea u i ṱanganedza.",
  "What is switched on for {value}. Changes apply to every user in the organisation, take effect on their next page load — the responder app follows within moments over realtime — and are written to the audit trail with your name.": "Zwo vulelwaho {value}. Tshanduko dzi shuma kha vhashumisi vhoṱhe kha dzangano, dzi thoma musi vha tshi longa siaṱari ḽi tevhelaho — app ya vhafhinduli i tevhela nga sekondo — nahone dzi ṅwalwa kha mukumbo wa u ṱola na dzina ḽaṋu.",
  "What is the damage?": "Tshinyalelo ndi mini?",
