  "Words not translated yet show in English. What people type, names and incident numbers stay as written.": "Maipfi a sa athu ṱalutshedzwa a sumbedzwa nga Luisimane. Zwine vhathu vha thaipha, madzina na nomboro dza zwiitea zwi dzula sa zwo ṅwalwaho.",
