  "Works once. Issued by {issuedBy}. Hand only to the person named above. Destroy after use.": "Zwi shuma luthihi. Zwo bviswa nga {issuedBy}. Ṋekedzani fhedzi muthu o bulwaho afho nṱha. Zwi tshinyeni nga murahu ha u shumiswa.",
