  "Your saved draft has been restored. Verify every answer before filing.": "Tshiṱoḓwa tshaṋu tsho vhulungwaho tsho vhuedzedzwa. Khwaṱhisedzani phindulo iṅwe na iṅwe ni sa athu rumela.",
  "Your saved draft has been restored. Verify every answer before signing.": "Tshiṱoḓwa tshaṋu tsho vhulungwaho tsho vhuedzedzwa. Khwaṱhisedzani phindulo iṅwe na iṅwe ni sa athu saina.",
  "Your session has expired — sign in again.": "U dzhena haṋu ho fhelelwa nga tshifhinga — dzhenani hafhu.",
  "Your session is safe. Tap below to retry — if it keeps happening, show this screen to your system administrator and fall back to radio.": "U dzhena haṋu ho tsireledzea. Kwatani afho fhasi u lingedza hafhu — arali zwi tshi bvela phanḓa zwi tshi itea, sumbedzani mulanguli wa sisiṱeme tshikirini itshi ni shumise radio.",
  "Your shift": "Tshifithi tshaṋu",
