  "Your {describe} for {value}'s {describe2}": "{describe} yaṋu ya {describe2} ya {value}",
  "Your {filedList} are signed and filed for today. Export a copy for your records, then continue to your dashboard.": "{filedList} yaṋu yo sainwa nahone yo rumelwa ṋamusi. Bvisani khophi ya rekhodo dzaṋu, ni bvele phanḓa kha dashibodo yaṋu.",
